  "Adaptive (default): follows your primary engine — a private primary keeps everything local, a public primary allows public engines. Public only: any public web/academic engine, no local sources. Private only: only local engines (library, paperless, etc.). Primary only: the selected search engine and nothing else. Unprotected: operator-enabled escape hatch that disables normal egress protection — not recommended (hard SSRF/cloud-metadata blocking still applies).": "自适应（默认）：跟随您的主引擎——私有主引擎保持一切本地化，公共主引擎允许公共引擎。仅公共：任何公共网络/学术引擎，无本地来源。仅私有：仅本地引擎（文献库、无纸化等）。仅主引擎：仅选定的搜索引擎，无其他。无保护：操作员启用的逃生舱，禁用正常的外部访问保护——不推荐（硬性SSRF/云元数据阻止仍然适用）。",
