  "Allow authenticated users to start, stop, and trigger the global news scheduler via API. This setting cannot be changed from the UI for security reasons. Disable in multi-user deployments by setting the environment variable LDR_NEWS_SCHEDULER_ALLOW_API_CONTROL=false.": "允许认证用户通过API启动、停止和触发全局新闻调度器。出于安全原因，此设置无法从UI更改。在多用户部署中，通过设置环境变量LDR_NEWS_SCHEDULER_ALLOW_API_CONTROL=false来禁用。",
  "Allow new user registrations through the web interface. Configured via LDR_APP_ALLOW_REGISTRATIONS environment variable. Set to 'false' to disable on public-facing deployments. Enabled by default so initial account creation works out of the box. Requires server restart.": "允许通过网页界面注册新用户。通过LDR_APP_ALLOW_REGISTRATIONS环境变量配置。设置为'false'可在面向公众的部署中禁用。默认启用，以便初始账户创建开箱即用。需要重启服务器。",
  "Allowed Local Hostnames": "允许的本地主机名",
  "Already Classified": "已分类",
  "Already Downloaded": "已下载",
  "Already Existed": "已存在",
  "Already added": "已添加",
  "Already scored in your per-user DB? Return instantly.": "已在您的个人数据库中评分？立即返回。",
  "Also drops journals with no signal in any bundled dataset (score 4): repository aggregators, garbled refs, brand-new venues with no h-index data.": "同时剔除在任何捆绑数据集中无信号的期刊（评分4）：存储库聚合器、乱码引用、无h指数数据的新期刊。",
  "Also drops moderate journals (score 5). Conferences and DOAJ-only OA journals start to disappear.": "同时剔除中等期刊（评分5）。会议和仅DOAJ的开放获取期刊开始消失。",
  "Also found in content": "也在内容中发现",
  "Also found in research content": "也在研究内容中发现",
  "Also import your Zotero PDF annotations (highlights + comments) and child notes, appended to the document's searchable text. Adds extra API calls per item, so it's off by default. Note: annotation/note edits that don't change the parent item are picked up only when the item itself changes.": "同时导入您的 Zotero PDF 注释（高亮和评论）及子笔记，并附加到文档的可搜索文本中。每个项目会增加额外的 API 调用，因此默认关闭。注意：不更改父项目的注释/笔记编辑仅在项目本身更改时才会被获取。",
  "Also save reports as files on disk for external access (reports are always stored in the database regardless). Enable this if you need to access reports from outside the web interface.": "同时将报告保存为磁盘上的文件以供外部访问（报告始终存储在数据库中，无论是否启用）。如果您需要从网页界面外部访问报告，请启用此选项。",
  "Also store the full PDF in the encrypted library": "同时将完整PDF存储在加密文献库中",
  "An error occurred": "发生错误",
  "An error occurred while starting research. Please try again.": "启动研究时发生错误。请重试。",
  "Analysis in progress...": "分析进行中...",
  "Analyze and categorize all domains using AI classification": "使用AI分类分析并归类所有域名",
  "Analyze sources and domains used in your research sessions": "分析您研究会话中使用的来源和域名",
  "Analyze today's financial markets and economic news from YYYY-MM-DD. Find UP TO 10 SIGNIFICANT market movements, economic events, or financial news items from today. CRITICAL: All information MUST be from real, verifiable sources. DO NOT invent or fabricate any market data or movements. Only report actual market information from reliable financial sources. Create a comprehensive table with these columns: | SOURCES | DATE | Market/Asset | Movement | Key Drivers | Analysis | Outlook | |---------|------|--------------|----------|-------------|----------|----------| | [Citation numbers] | [YYYY-MM-DD] | [Asset name] | [% change] | [Main reason] | [Impact analysis] | [Next 24h outlook] | IMPORTANT: In the SOURCES column, list the citation numbers (e.g., [1, 3, 5]) that support this data. These should match the numbered references at the end of your report. Focus on finding 10 DISTINCT market events: - Major stock indices (S&P 500, NASDAQ, DOW) - Cryptocurrency movements - Commodity prices (Oil, Gold, etc.) - Currency pairs - Notable company earnings or news - IPOs, mergers, or acquisitions - Central bank decisions - Economic indicators (GDP, inflation, employment) Each row should be a SEPARATE market event or movement, not multiple updates about the same thing. Include market sentiment analysis and tomorrow's key events to watch. REQUIREMENTS: - Only use real market data from verified sources - Do not invent prices, movements, or market events - If data is unavailable, state so rather than fabricating": "分析YYYY-MM-DD的今日金融市场和经济新闻。查找今日最多10个重要市场变动、经济事件或金融新闻。关键：所有信息必须来自真实、可验证的来源。不要编造或虚构任何市场数据或变动。仅报告来自可靠金融来源的实际市场信息。创建包含以下列的综合表格：| 来源 | 日期 | 市场/资产 | 变动 | 关键驱动因素 | 分析 | 展望 | |---------|------|--------------|----------|-------------|----------|----------| | [引用编号] | [YYYY-MM-DD] | [资产名称] | [%变动] | [主要原因] | [影响分析] | [未来24小时展望] | 重要：在来源列中，列出支持此数据的引用编号（例如，[1, 3, 5]）。这些应与报告末尾的编号引用相匹配。专注于查找10个不同的市场事件：- 主要股票指数（标普500、纳斯达克、道琼斯）- 加密货币变动 - 大宗商品价格（石油、黄金等）- 货币对 - 显著的公司盈利或新闻 - IPO、并购 - 央行决策 - 经济指标（GDP、通胀、就业）每行应为独立的市场事件或变动，而非同一事物的多次更新。包括市场情绪分析和明日需关注的关键事件。要求：- 仅使用来自已验证来源的真实市场数据 - 不要编造价格、变动或市场事件 - 如果数据不可用，请说明而非虚构",
  "Analyzing gathered information...": "正在分析收集的信息...",
  "Analyzing news... Results will appear below when ready.": "正在分析新闻... 结果将在准备好后显示在下方。",
