  "Application": "应用",
  "Apply an LLM relevance filter to local document / collection (RAG) results. Embeddings already rank by similarity, so this is optional; enabling it prunes semantically-near-but-irrelevant chunks at the cost of one extra LLM call per search.": "对本地文档/资料合集（RAG）结果应用 LLM 相关性过滤器。嵌入已按相似度排序，因此这是可选的；启用它会修剪语义相近但不相关的片段，代价是每次搜索额外调用一次 LLM。",
  "ArXiv is a shared resource containing only academic papers - benchmarking with SimpleQA is useless as it will find zero relevant results for general knowledge questions. Should not be used for this test. Use Tavily instead.": "ArXiv 是仅包含学术论文的共享资源——使用 SimpleQA 进行基准测试毫无用处，因为对于一般知识问题它将找到零个相关结果。不应用于此测试。请改用 Tavily。",
  "Are you sure you want to cancel and delete this running benchmark? This action cannot be undone.": "您确定要取消并删除此正在运行的基准测试吗？此操作无法撤销。",
  "Are you sure you want to cancel this research?": "您确定要取消此研究吗？",
  "Are you sure you want to clear all research history? This also permanently deletes ALL your chat sessions and their conversations. This action cannot be undone.": "您确定要清除所有研究历史吗？这也会永久删除您所有的聊天会话及其对话。此操作无法撤销。",
  "Are you sure you want to delete \"{{0}}\"? Documents that belong only to this collection will be deleted with it. This action cannot be undone.": "您确定要删除“{{0}}”吗？仅属于此资料合集的文档将随之删除。此操作无法撤销。",
  "Are you sure you want to delete the subscription \"{{0}}\"?": "您确定要删除订阅“{{0}}”吗？",
  "Are you sure you want to delete this chat session? This action cannot be undone.": "您确定要删除此聊天会话吗？此操作无法撤销。",
  "Are you sure you want to delete this item?": "您确定要删除此项目吗？",
  "Are you sure you want to delete this note? This action cannot be undone.": "您确定要删除此笔记吗？此操作无法撤销。",
  "Are you sure you want to delete this research? This action cannot be undone.": "您确定要删除此研究吗？此操作无法撤销。",
  "Are you sure you want to delete this subscription?": "您确定要删除此订阅吗？",
  "Are you sure you want to reset ALL settings to their default values? This cannot be undone.": "您确定要将所有设置重置为默认值吗？此操作无法撤销。",
  "Are you sure?": "您确定吗？",
