  "Arxiv": "arXiv",
  "Ascending": "升序",
  "Ask": "提问",
  "Ask a Question": "提问",
  "Ask a follow-up question based on your previous research. This will use the context and sources from your last research to provide more focused results.": "基于您之前的研究提出后续问题。这将使用您上次研究的上下文和来源，以提供更聚焦的结果。",
  "Ask a follow-up question using this research's sources and context": "使用此研究的来源和上下文提出后续问题",
  "Ask a question...": "提问...",
  "Ask anything. Follow up to dig deeper. Every answer is grounded in sources.": "询问任何问题。跟进以深入探讨。每个答案都有来源依据。",
  "Ask your notes a question": "向您的笔记提问",
  "Ask your notes a question...": "向您的笔记提问...",
  "Ask: Compare renewable energy sources for home use": "提问：比较家庭使用的可再生能源",
  "Ask: Explain quantum computing in simple terms": "提问：用简单的术语解释量子计算",
  "Ask: What are effective strategies for improving sleep quality?": "提问：改善睡眠质量的有效策略有哪些？",
  "Ask: What are the latest developments in AI research?": "提问：AI 研究的最新进展是什么？",
  "Assistant": "助手",
  "At least 3 characters. Letters, numbers, underscores, and hyphens only.": "至少3个字符。仅限字母、数字、下划线和连字符。",
  "Atlas Cloud API Key": "Atlas Cloud API 密钥",
  "Attempt to retrieve full-text articles from PubMed Central (PMC). Only works for open-access papers.": "尝试从PubMed Central（PMC）检索全文文章。仅适用于开放获取论文。",
  "Authentication Issues": "认证问题",
