  "Auto-refresh enabled (every 5 minutes)": "自动刷新已启用（每5分钟）",
  "Auto-refresh is disabled. Set LDR_NEWS_SCHEDULER_ALLOW_API_CONTROL=true to enable manual control.": "自动刷新已禁用。设置LDR_NEWS_SCHEDULER_ALLOW_API_CONTROL=true以启用手动控制。",
  "Automatic Scoring": "自动评分",
  "Automatically adjust the search period based on the query type (recent or historical) to improve news search relevance": "根据查询类型（近期或历史）自动调整搜索周期，以提高新闻搜索相关性",
  "Automatically backup database after successful login. Each backup uses disk space proportional to your database size. Disable this if disk space is limited.": "成功登录后自动备份数据库。每次备份使用的磁盘空间与数据库大小成比例。如果磁盘空间有限，请禁用此功能。",
  "Automatically download PDF files during scheduled document processing. Files will be stored on disk (requires storage space). WARNING: Downloaded files are stored unencrypted on disk.": "在计划文档处理期间自动下载 PDF 文件。文件将存储在磁盘上（需要存储空间）。警告：下载的文件以未加密形式存储在磁盘上。",
  "Automatically index documents for RAG search when they are added to collections (via upload or download). Indexing runs in the background without blocking uploads. Disable to defer indexing and improve upload speed for large batches.": "当文档添加到资料合集（通过上传或下载）时，自动为RAG搜索索引文档。索引在后台运行，不会阻塞上传。禁用可延迟索引并提高大批量上传速度。",
  "Automatically optimize natural language queries for PubMed's specialized syntax (MeSH terms, Boolean operators).": "自动优化自然语言查询以适应PubMed的专用语法（MeSH术语、布尔运算符）。",
  "Automatically sync in the background": "在后台自动同步",
  "Available export format options displayed in the user interface. Supported formats include Markdown (.md), LaTeX (.tex), Quarto (.qmd), and RIS bibliographic format.": "用户界面中可用的导出格式选项。支持的格式包括Markdown（.md）、LaTeX（.tex）、Quarto（.qmd）和RIS书目格式。",
