  "Changes save automatically. These settings are used as defaults for new collections; existing collections continue using their current settings unless re-indexed.": "更改会自动保存。这些设置将作为新资料合集的默认值；现有资料合集将继续使用其当前设置，除非重新索引。",
  "Changing encryption settings requires deleting existing databases and creating new ones. There is no migration path.": "更改加密设置需要删除现有数据库并创建新数据库。没有迁移路径。",
  "Changing these settings will only affect NEW collections.": "更改这些设置只会影响新的资料合集。",
  "Characters for recursive/semantic; tokens for token and sentence (sentence is capped by the tokenizer's max length).": "字符用于递归/语义；令牌用于令牌和句子（句子受分词器最大长度限制）。",
  "Characters shared between adjacent chunks. Prevents important information from being cut at chunk boundaries. Typically 10-20% of chunk size. Affects new indexing only.": "相邻块之间共享的字符。防止重要信息在块边界被截断。通常为块大小的 10-20%。仅影响新索引。",
