  "Checked (default): the LangGraph research agent can search this collection as one of its tools. Uncheck to keep it out of the agent's tool list when it isn't needed for agentic research.": "已选中（默认）：LangGraph 研究代理可以将此资料合集作为其工具之一进行搜索。取消选中以在代理研究不需要时将其排除在代理的工具列表之外。",
  "Checked (default): the LangGraph research agent can search this collection as one of its tools. Uncheck to keep the collection out of the agent's tool list when you don't need it for agentic research.": "已选中（默认）：LangGraph 研究代理可以将此资料合集作为其工具之一进行搜索。当您不需要它进行代理研究时，取消选中以将资料合集排除在代理的工具列表之外。",
