  "Chinese": "中文",
  "Choose \"Quick\" mode for basic queries": "为基本查询选择“快速”模式",
  "Choose a name that clearly describes what documents will be in this collection (e.g., \"Research Papers on AI Ethics\", \"Product Documentation 2025\")": "选择一个能清楚描述此资料合集中文档的名称（例如，“AI 伦理研究论文”、“产品文档 2025”）",
  "Choose a username": "选择用户名",
  "Choose how PDFs are stored. Each user has their own encrypted database. Database mode stores PDFs encrypted within it (secure, portable, isolated per-user). Filesystem mode stores unencrypted files on disk (faster for large files). None stores only extracted text (smallest footprint).": "选择 PDF 的存储方式。每个用户拥有自己的加密数据库。数据库模式将 PDF 加密存储在数据库中（安全、便携、按用户隔离）。文件系统模式将未加密文件存储在磁盘上（对于大文件更快）。无模式仅存储提取的文本（占用空间最小）。",
  "Choose how to store uploaded PDF files:": "选择如何存储上传的 PDF 文件：",
  "Choose how to store your research PDFs:": "选择如何存储您的研究 PDF：",
  "Choose how user-uploaded PDFs are stored. Database mode stores PDFs encrypted in your personal database (increases database size but allows viewing/downloading later). Text Only extracts and stores only the text content (smallest footprint). Note: Filesystem storage is not available for uploads for security reasons.": "选择用户上传的PDF文件的存储方式。数据库模式将PDF加密存储在您的个人数据库中（会增加数据库大小，但便于日后查看/下载）。仅文本模式仅提取并存储文本内容（占用空间最小）。注意：出于安全原因，上传不支持文件系统存储。",
  "Choose the search strategy that best fits your needs": "选择最适合您需求的搜索策略",
  "Choose update frequency: hourly, daily, or weekly. Adjust based on topic volatility.": "选择更新频率：每小时、每天或每周。根据主题变化程度进行调整。",
  "Choose where to store downloaded PDFs:": "选择下载的 PDF 存储位置：",
  "Choose which collection to add downloaded documents to for organized searching.": "选择将下载的文档添加到哪个资料合集，以便进行有序搜索。",
