  "Citation formatting style for reports. Options include numbered hyperlinks [1], domain-based hyperlinks [arxiv.org], smart domain numbering [arxiv.org-1], source-tagged citations with the global citation number preserved (e.g. [arxiv-1], [openai.com-2], [arxiv-3]), and plain numbered references without links.": "报告引用的格式化样式。选项包括编号超链接[1]、基于域名的超链接[arxiv.org]、智能域名编号[arxiv.org-1]、保留全局引用编号的来源标记引用（例如[arxiv-1]、[openai.com-2]、[arxiv-3]），以及无链接的纯编号引用。",
