  "Context overflow detected.": "检测到上下文溢出。",
  "Context overflow notice": "上下文溢出通知",
  "Context truncated {{0}} time(s) during research.": "研究过程中上下文被截断 {{0}} 次。",
  "Context utilization": "上下文利用率",
  "Context window size (in tokens) used when generating Ollama embeddings. Must be at least as large as the longest chunk after tokenization; otherwise Ollama returns 'input length exceeds the context length' (HTTP 500) and indexing fails. The default of 8192 covers chunk sizes up to ~5000 characters for most models. Increase for very large chunks; decrease to save VRAM. qwen3-embedding supports up to 32768; nomic-embed-text supports 8192.": "生成Ollama嵌入时使用的上下文窗口大小（以令牌计）。必须至少与分词后最长的块一样大；否则Ollama会返回“输入长度超过上下文长度”（HTTP 500）且索引失败。默认值8192覆盖大多数模型约5000字符的块大小。对于非常大的块请增加；为节省显存可减少。qwen3-embedding支持高达32768；nomic-embed-text支持8192。",
  "Context window size in tokens (512-131072) ·": "上下文窗口大小（以令牌计，512-131072）·",
  "Context window size in tokens for local LLMs (Ollama, LlamaCpp, LM Studio). The default of 20480 tokens fits on systems with limited VRAM while still leaving room for the synthesis prompt. If your synthesis prompts get truncated, increase this; if you run out of VRAM, reduce it and switch to the source-based strategy.": "本地大语言模型（Ollama、LlamaCpp、LM Studio）的上下文窗口大小（以令牌计）。默认值20480令牌适用于显存有限的系统，同时为综合提示留出空间。如果综合提示被截断，请增大此值；如果显存不足，请减小此值并切换到基于来源的策略。",
  "Contradicted": "矛盾",
  "Control:": "控制：",
  "Controls randomness in model outputs. Lower values (0.0-0.3) produce deterministic, factual responses; higher values (0.7-1.0) produce more creative and varied outputs.": "控制模型输出的随机性。较低的值（0.0-0.3）产生确定性、事实性的响应；较高的值（0.7-1.0）产生更具创造性和多样性的输出。",
  "Controls the LangGraph agent's fetch_content tool. 'summary_focus_query' (default) asks the LLM to extract only spans relevant to a focus question the agent supplies per call AND the original research query, so vague focus can be disambiguated — keeps small-model context clean. 'summary_focus' is the same but uses only the per-call focus question. 'full' returns the entire extracted page text (legacy behavior; can flood small-model context with boilerplate/metadata and degrade benchmark accuracy). 'disabled' removes the tool entirely so the agent works from search snippets only — useful for diagnosing whether fetching is helping or hurting accuracy.": "控制LangGraph代理的fetch_content工具。'summary_focus_query'（默认）要求LLM仅提取与代理每次调用提供的焦点问题以及原始研究查询相关的片段，因此模糊焦点可以被消歧——保持小模型上下文干净。'summary_focus'相同，但仅使用每次调用的焦点问题。'full'返回提取的整个页面文本（旧行为；可能用小模型的上下文淹没样板/元数据并降低基准准确性）。'disabled'完全移除该工具，使代理仅基于搜索片段工作——用于诊断获取是否有助于或损害准确性。",
  "Converting research to documents...": "正在将研究转换为文档...",
