  "Custom base URL for the embeddings endpoint. Leave blank to use the OpenAI cloud API (https://api.openai.com/v1). Set to your OpenAI-compatible local server URL to route embeddings there — examples: http://localhost:1234/v1 (LM Studio), http://localhost:8000/v1 (vLLM or llama.cpp server). When set, this overrides the cloud endpoint for embeddings without affecting the chat LLM provider.": "嵌入端点的自定义基础URL。留空以使用OpenAI云API（https://api.openai.com/v1）。设置为与OpenAI兼容的本地服务器URL以将嵌入路由到那里——示例：http://localhost:1234/v1（LM Studio）、http://localhost:8000/v1（vLLM或llama.cpp服务器）。设置后，此设置将覆盖嵌入的云端点，而不影响聊天LLM提供方。",
