  "ERROR: Failed to load": "错误：加载失败",
  "ERROR: No value": "错误：无值",
  "EXPERIMENTAL — this egress boundary is new defense-in-depth, not an absolute guarantee yet; don't rely on it as your only protection for highly sensitive data. Restrict which search engines a research run may use. ADAPTIVE (default) = follow your primary engine: a private primary keeps everything local, a public primary allows public engines. STRICT = only the primary engine you picked; PUBLIC_ONLY = any public web/academic engine; PRIVATE_ONLY = any local engine (library, paperless, etc.); UNPROTECTED = operator-enabled escape hatch that disables egress protection entirely (not recommended; requires LDR_POLICY_ALLOW_UNPROTECTED_EGRESS=true; hard SSRF/cloud-metadata blocking still applies).": "实验性——此外部访问边界是新的纵深防御，尚非绝对保证；不要将其作为高度敏感数据的唯一保护。限制研究运行可使用的搜索引擎。ADAPTIVE（默认）= 跟随您的主引擎：私有主引擎保持一切本地化，公共主引擎允许公共引擎。STRICT = 仅使用您选择的主引擎；PUBLIC_ONLY = 任何公共网络/学术引擎；PRIVATE_ONLY = 任何本地引擎（文献库、paperless等）；UNPROTECTED = 操作员启用的逃生舱，完全禁用外部访问保护（不推荐；需要LDR_POLICY_ALLOW_UNPROTECTED_EGRESS=true；硬性SSRF/云元数据阻止仍然适用）。",
  "EXPERIMENTAL. LLM/embeddings providers you explicitly trust to receive sensitive content — listing one treats it as a 'contained' inference sink even though it is off-machine (e.g. a zero-retention enterprise Anthropic endpoint). Relaxes the two-axis egress classification; use only for providers you have vetted.": "实验性。您明确信任可接收敏感内容的LLM/嵌入提供方——列出一个即将其视为“受控”推理汇，即使它在机器外（例如零保留的企业Anthropic端点）。放宽双轴外部访问分类；仅用于您已审查的提供方。",
  "EXPERIMENTAL. Search engines whose endpoint you explicitly trust — listing one (e.g. a self-hosted Elasticsearch/Paperless on a public hostname) treats it as 'contained' rather than an exposing sink. Relaxes the two-axis egress classification; use only for endpoints you control.": "实验性。您明确信任其端点的搜索引擎——列出一个（例如公共主机名上的自托管Elasticsearch/Paperless）即将其视为“受控”而非暴露汇。放宽双轴外部访问分类；仅用于您控制的端点。",
  "Each chunk is converted to a vector (list of numbers) that captures its meaning.": "每个块被转换为向量（数字列表），以捕获其含义。",
  "Each cycle: AI generates follow-up questions based on what it found, then searches again. Searches run in parallel. More iterations = deeper coverage but longer wait.": "每个周期：AI根据已发现的内容生成后续问题，然后再次搜索。搜索并行运行。迭代次数越多 = 覆盖越深但等待时间越长。",
  "Each journal flows through these tiers in order. The first tier that returns a score wins, so the expensive tiers (institution lookup, LLM) only run when the cheap ones can't answer.": "每个期刊按顺序通过这些层级。第一个返回分数的层级获胜，因此昂贵的层级（机构查询、LLM）仅在廉价层级无法回答时运行。",
