  "Final Max Results": "最终最大结果数",
  "Find UP TO 10 IMPORTANT technology news stories and updates from today YYYY-MM-DD. CRITICAL: All information MUST be from real, verifiable sources. DO NOT invent or fabricate any tech news, announcements, or details. Only report what you find from actual technology news sources. Format as a table: | SOURCES | DATE | Company/Topic | Announcement | Impact | Technical Details | Market Reaction | |---------|------|---------------|--------------|--------|-------------------|------------------| | [Citation numbers] | [YYYY-MM-DD] | [Company/Tech] | [What was announced] | [Industry impact] | [Technical specifics] | [Stock/Market response] | IMPORTANT: In the SOURCES column, list the citation numbers (e.g., [1, 3, 5]) that support this news. These should match the numbered references at the end of your report. Cover 10 DISTINCT technology stories from: - AI/ML developments - Major tech company news - Cybersecurity updates - Product launches - Research breakthroughs - Industry trends - Startup funding rounds - Tech policy and regulation - Open source projects - Hardware innovations Each row should be a SEPARATE tech news item, not multiple angles of the same story. Focus on developments with significant industry impact. REQUIREMENTS: - Only include real announcements from verified sources - Do not fabricate company news or technical details - If insufficient news is found, include fewer rows rather than inventing content": "查找今天 YYYY-MM-DD 的至多 10 条重要科技新闻和更新。关键：所有信息必须来自真实、可验证的来源。不要编造或虚构任何科技新闻、公告或细节。只报告您从实际科技新闻来源中找到的内容。格式为表格：| 来源 | 日期 | 公司/主题 | 公告 | 影响 | 技术细节 | 市场反应 | |---------|------|---------------|--------------|--------|-------------------|------------------| | [引用编号] | [YYYY-MM-DD] | [公司/技术] | [公告内容] | [行业影响] | [技术细节] | [股票/市场反应] | 重要：在来源列中，列出支持此新闻的引用编号（例如，[1, 3, 5]）。这些编号应与报告末尾的编号引用一致。涵盖 10 条不同的科技新闻，来自：- AI/ML 进展 - 主要科技公司新闻 - 网络安全更新 - 产品发布 - 研究突破 - 行业趋势 - 初创公司融资轮次 - 科技政策与监管 - 开源项目 - 硬件创新 每行应为独立的科技新闻条目，而非同一新闻的多个角度。重点关注具有重大行业影响的发展。要求：- 仅包含来自已验证来源的真实公告 - 不要编造公司新闻或技术细节 - 如果找到的新闻不足，减少行数而非虚构内容",
  "Find notes, library documents, and research reports in one place": "在一个地方查找笔记、文献库文档和研究报告",
  "Findings are synthesized into a comprehensive report with citations and references.": "研究结果被综合成一份包含引文和参考文献的全面报告。",
