  "Follow-up Context Mode": "后续上下文模式",
  "Follow-up Research": "后续研究",
  "Follow-up questions in each cycle": "每个周期中的后续问题",
  "Follow-up questions per cycle. Multiplies with iterations: 3 questions × 4 iterations = 12 searches. More = broader but slower/costlier.": "每个周期的后续问题。与迭代次数相乘：3个问题 × 4次迭代 = 12次搜索。更多=更广泛但更慢/更昂贵。",
  "For academic research, select ArXiv or PubMed as your search engine. For general topics, SearXNG provides the broadest coverage.": "对于学术研究，请选择ArXiv或PubMed作为搜索引擎。对于一般主题，SearXNG提供最广泛的覆盖范围。",
  "For accurate benchmark grading, use flagship models from major providers like Claude Sonnet series or GPT-4 class models. Local models and smaller cloud models may produce inconsistent evaluations, affecting benchmark accuracy scores. However, preliminary tests indicate that local models might be adequate for performance evaluation if highest grade standards are not required.": "为了准确的基准评分，请使用主要提供方的旗舰模型，如Claude Sonnet系列或GPT-4类模型。本地模型和较小的云模型可能产生不一致的评估，影响基准准确度分数。然而，初步测试表明，如果不需要最高评分标准，本地模型可能足以用于性能评估。",
  "For preprints (arXiv, bioRxiv, …) without a journal, fall back to scoring the author's institution using ~120K OpenAlex Institutions records (h-index ≥ 250 → 6, ≥ 50 → 5, else → 4). Capped — never beats a real venue match.": "对于没有期刊的预印本（arXiv、bioRxiv等），回退到使用约12万条OpenAlex机构记录对作者所在机构进行评分（h指数≥250→6，≥50→5，否则→4）。有上限——永远不会超过真实的期刊匹配。",
  "For testing only:": "仅用于测试：",
  "Force reclassification of all domains (overwrite existing)": "强制重新分类所有域名（覆盖现有）",
  "Forced on by the Private-only egress scope — local inference is required so data stays on this machine.": "由仅限私有的外部访问范围强制启用——需要本地推理，以便数据保留在此机器上。",
  "Forest": "森林",
