  "H-Index": "H指数",
  "H-index has field-dependent bias — mathematics journals naturally have lower h-index than biomedical journals.": "H指数存在领域偏差——数学期刊的H指数自然低于生物医学期刊。",
  "HEADLINE": "标题",
