  "HNSW (Fast, large collections)": "HNSW（快速，大型资料合集）",
  "HNSW recommended for >10K documents (50-60× faster)": "HNSW 推荐用于超过1万篇文档（快50-60倍）",
  "HTTP endpoint URL where LM Studio is running locally. Include the full path (e.g., http://localhost:1234/v1 for OpenAI-compatible API format).": "LM Studio 本地运行的 HTTP 端点 URL。包含完整路径（例如，http://localhost:1234/v1 用于 OpenAI 兼容 API 格式）。",
  "HTTP endpoint URL where Ollama is running. Used to connect to local or remote Ollama instances for model inference.": "Ollama 运行的 HTTP 端点 URL。用于连接本地或远程 Ollama 实例进行模型推理。",
  "HTTP endpoint URL where llama.cpp's `llama-server` is running. Include the full path with /v1 (default: http://localhost:8080/v1). Run `llama-server -m <model.gguf>` to start it.": "llama.cpp 的 `llama-server` 运行的 HTTP 端点 URL。包含带 /v1 的完整路径（默认：http://localhost:8080/v1）。运行 `llama-server -m <model.gguf>` 启动它。",
  "HTTP error {{0}}": "HTTP 错误 {{0}}",
  "HTTP error! status: {{0}}": "HTTP 错误！状态：{{0}}",
  "HTTP {{0}}: {{1}}": "HTTP {{0}}：{{1}}",
  "Hard wall-clock timeout (seconds) for the LLM call that generates a chat session title. Past this, the request thread falls back to truncation so a slow LLM endpoint cannot block title generation indefinitely.": "生成聊天会话标题的 LLM 调用的硬性墙钟超时（秒）。超过此时间，请求线程回退到截断，因此慢速 LLM 端点不会无限期阻塞标题生成。",
  "Has PDFs": "有 PDF",
  "Heading": "标题",
  "Health": "健康",
  "Help panel dismissed": "帮助面板已关闭",
  "Help panels reset": "帮助面板已重置",
  "Hidden Costs:": "隐藏成本：",
  "Hidden from the LangGraph research agent's tool list (check “Available to the research agent” on the collection page to re-enable).": "从 LangGraph 研究代理的工具列表中隐藏（在资料合集页面上勾选“对研究代理可用”以重新启用）。",
  "Hide JSON Configuration": "隐藏 JSON 配置",
