  "JSON array of separator strings tried in order by the recursive splitter. The default works for general prose. For code, add language-specific separators like \"\\nclass\", \"\\ndef\".": "递归分割器按顺序尝试的分隔符字符串的JSON数组。默认适用于一般散文。对于代码，添加特定于语言的分隔符，如\"\\nclass\"、\"\\ndef\"。",
  "JSON array of separators. Default works for 80% of use cases. Used by recursive and semantic splitters only — token and sentence ignore this. For code, add language-specific separators like \"\\nclass\", \"\\ndef\".": "分隔符的JSON数组。默认适用于80%的使用场景。仅递归和语义分割器使用——令牌和句子忽略此项。对于代码，添加特定语言的分隔符，如\"\\nclass\"、\"\\ndef\"。",
