  "Journal quality data appears here as you run research with academic search engines (ArXiv, OpenAlex, Semantic Scholar, NASA ADS).": "当您使用学术搜索引擎（ArXiv、OpenAlex、Semantic Scholar、NASA ADS）进行研究时，期刊质量数据会显示在此处。",
  "Journal quality data is not installed. Fetch it from OpenAlex (sources + institutions), DOAJ, JabRef, and Stop Predatory Journals to enable scoring and this dashboard (~7 min one-time download, ~25 MB on disk).": "期刊质量数据未安装。从OpenAlex（来源+机构）、DOAJ、JabRef和Stop Predatory Journals获取以启用评分和此仪表板（一次性下载约7分钟，磁盘占用约25 MB）。",
  "Journal quality scores are automatically collected as you run research. Start a research session with academic sources (ArXiv, OpenAlex, Semantic Scholar, NASA ADS) enabled.": "期刊质量评分会在您进行研究时自动收集。启用学术来源（ArXiv、OpenAlex、Semantic Scholar、NASA ADS）开始研究会话。",
  "Journal quality scoring is built on freely-licensed bibliographic data from": "期刊质量评分基于来自以下来源的自由许可书目数据",
