  "Keeps only Nature/Science/NEJM-tier journals (h-index > 150). Almost everything will be filtered out.": "仅保留Nature/Science/NEJM级别的期刊（h指数>150）。几乎所有内容都会被过滤掉。",
  "Keeps only journals with h-index > 20. About 60% of OpenAlex sources fall below this.": "仅保留h指数>20的期刊。约60%的OpenAlex来源低于此标准。",
  "Keeps only strong Q1 journals (h-index > 40). Most search results will be filtered.": "仅保留强Q1期刊（h指数>40）。大多数搜索结果将被过滤。",
  "Keeps only top journals with h-index > 75. Very aggressive — expect ~80–90% of results to be removed.": "仅保留h指数>75的顶级期刊。非常严格——预计约80–90%的结果会被移除。",
  "Key Concepts": "关键概念",
  "Key advantages of Brave: Privacy-focused, good semantic search, reasonable pricing, full-text retrieval available.": "Brave的主要优势：注重隐私、良好的语义搜索、合理的定价、可进行全文检索。",
  "Key advantages of GitHub: Excellent for code/technical queries, includes README content, issue discussions, works without API key.": "GitHub的主要优势：非常适合代码/技术查询，包含README内容、问题讨论，无需API密钥即可使用。",
  "Key advantages of Mojeek: Privacy-focused with own independent web index, no tracking.": "Mojeek的主要优势：注重隐私，拥有独立的网络索引，无跟踪。",
  "Key advantages of PubMed: Peer-reviewed biomedical literature, MeSH indexing, abstracts, citation data, free access.": "PubMed的主要优势：同行评审的生物医学文献、MeSH索引、摘要、引文数据、免费访问。",
  "Key advantages of SearXNG: Free, self-hosted, privacy-respecting, aggregates multiple engines, no API limits.": "SearXNG的主要优势：免费、自托管、尊重隐私、聚合多个引擎、无API限制。",
  "Key advantages of arXiv: Free access to preprints, covers physics/math/CS/biology, fast publication of cutting-edge research.": "arXiv的主要优势：免费访问预印本，涵盖物理/数学/计算机科学/生物学，快速发布前沿研究。",
  "Key derivation iterations (current: 256000)": "密钥派生迭代次数（当前：256000）",
  "Key strengths of Open Library.": "开放图书馆的主要优势。",
  "Key strengths of Project Gutenberg.": "古腾堡计划的主要优势。",
  "Key strengths of PubChem.": "PubChem的主要优势。",
  "Key strengths of Stack Exchange.": "Stack Exchange的主要优势。",
  "Key strengths of Zenodo.": "Zenodo的主要优势。",
