  "Knowledge Accumulation": "知识积累",
  "Knowledge Accumulation Context Limit": "知识积累上下文限制",
  "L2-normalize embedding vectors after generation. Recommended: ensures fair similarity comparison regardless of source document length. Some embedding models already produce normalized output; in that case this is a no-op.": "生成后对嵌入向量进行L2归一化。推荐：确保无论源文档长度如何，相似性比较都公平。某些嵌入模型已产生归一化输出；在这种情况下，此操作无效。",
