  "LLM Title Generation": "LLM标题生成",
  "LLM locality is locked by the server operator.": "LLM本地性由服务器运营商锁定。",
  "LLM model used as a judge to score benchmark answers against reference answers (e.g., 'anthropic/claude-3.7-sonnet' for OpenRouter, 'gpt-4o' for OpenAI). Must be compatible with the selected evaluation provider.": "用作评判模型的LLM，用于对基准答案与参考答案进行评分（例如，OpenRouter的'anthropic/claude-3.7-sonnet'，OpenAI的'gpt-4o'）。必须与所选评估提供方兼容。",
  "LLM provider used to grade benchmark answers by comparing research outputs against reference answers. This is separate from the research LLM being tested. Options: openai_endpoint (recommended, supports OpenRouter), openai, anthropic, ollama.": "用于对基准答案进行评分的LLM提供方，通过将研究输出与参考答案进行比较。这与被测试的研究LLM是分开的。选项：openai_endpoint（推荐，支持OpenRouter）、openai、anthropic、ollama。",
  "LLM rating breakdown": "LLM评分明细",
  "LM Studio (Local)": "LM Studio（本地）",
  "LM Studio API Key (Optional)": "LM Studio API密钥（可选）",
  "LM Studio Endpoint": "LM Studio端点",
  "LOCATION: [ENTER YOUR CITY/REGION HERE] Find UP TO 10 LOCAL NEWS ITEMS for the specified location from today YYYY-MM-DD. START YOUR RESPONSE DIRECTLY WITH THE TABLE. NO INTRODUCTION. CRITICAL: All information MUST be from real, verifiable local sources. DO NOT invent or fabricate any local news, events, or details. Only report what you find from actual local news sources. OUTPUT FORMAT: | SOURCE | DATE | HEADLINE | CATEGORY | DETAILS | IMPACT ON COMMUNITY | |--------|------|----------|----------|---------|---------------------| | [Citation numbers] | [YYYY-MM-DD] | [Brief headline] | [Local Gov/Crime/Business/Community/Weather] | [What happened] | [How it affects residents] | IMPORTANT: In the SOURCE column, list the citation numbers (e.g., [1, 3, 5]) that support this news. These should match the numbered references at the end of your report. Include UP TO 10 DISTINCT local stories from: - Local government decisions - Community events - Crime and safety updates - Business openings/closures - Infrastructure changes - Weather impacts - School and education news - Local sports and recreation - Health and public services - Transportation updates Each row should be a SEPARATE local event, not multiple updates about the same story. IMPORTANT: Focus ONLY on news from the location specified at the top. REQUIREMENTS: - Only use real local news from verified sources - Do not invent local events or incidents - If insufficient local news is found, include fewer rows rather than fabricating content": "位置：[在此处输入您的城市/地区] 查找指定位置今天（YYYY-MM-DD）最多10条本地新闻。直接以表格开始您的回复。不要引言。关键：所有信息必须来自真实、可验证的本地来源。不要编造任何本地新闻、事件或细节。只报告您从实际本地新闻来源找到的内容。输出格式：| 来源 | 日期 | 标题 | 类别 | 详情 | 对社区的影响 | |--------|------|----------|----------|---------|---------------------| | [引用编号] | [YYYY-MM-DD] | [简要标题] | [地方政府/犯罪/商业/社区/天气] | [发生了什么] | [对居民的影响] | 重要：在来源列中，列出支持此新闻的引用编号（例如，[1, 3, 5]）。这些应与报告末尾的编号参考文献匹配。包括最多10条不同的本地故事，来自：- 地方政府决策 - 社区活动 - 犯罪与安全更新 - 商业开业/关闭 - 基础设施变化 - 天气影响 - 学校与教育新闻 - 本地体育与娱乐 - 健康与公共服务 - 交通更新 每行应为单独的本地事件，而不是同一故事的多个更新。重要：只关注顶部指定位置的新闻。要求：- 仅使用来自已验证来源的真实本地新闻 - 不要编造本地事件或事故 - 如果找到的本地新闻不足，减少行数而不是编造内容",
