  "Limitations of Brave: Smaller index than Google, requires paid API for production use.": "Brave的局限性：索引比Google小，生产环境使用需要付费API。",
  "Limitations of GitHub: Limited to code/technical content, strict rate limits without authentication.": "GitHub的局限性：仅限于代码/技术内容，无认证时速率限制严格。",
  "Limitations of Mojeek: Smaller index than Google/Bing, requires paid API key.": "Mojeek的局限性：索引比Google/Bing小，需要付费API密钥。",
  "Limitations of Open Library.": "开放图书馆的局限性。",
  "Limitations of Project Gutenberg.": "古腾堡计划的局限性。",
  "Limitations of PubChem.": "PubChem的局限性。",
  "Limitations of PubMed: Limited to biomedical literature, keyword-based search, full-text only for open-access papers.": "PubMed的局限性：仅限于生物医学文献，基于关键词搜索，仅开放获取论文可全文访问。",
  "Limitations of SearXNG: Requires self-hosting, public instances may have rate limits, result quality varies.": "SearXNG的局限性：需要自托管，公共实例可能有速率限制，结果质量参差不齐。",
  "Limitations of Stack Exchange.": "Stack Exchange的局限性。",
  "Limitations of Zenodo.": "Zenodo的局限性。",
  "Limitations of arXiv: Preprints aren't peer-reviewed, limited to STEM fields, keyword-based search may miss semantic matches.": "arXiv的局限性：预印本未经同行评审，仅限于STEM领域，基于关键词搜索可能遗漏语义匹配。",
  "Limitations: Less coverage of specialized topics, variable article quality, not ideal for breaking news.": "局限性：专业主题覆盖较少，文章质量参差不齐，不适合突发新闻。",
  "Limitations: May lag on recent events, less depth on specialized academic topics, no product comparisons.": "局限性：近期事件可能滞后，专业学术主题深度不足，无产品比较。",
  "Limitations: Only finds previously archived content, may miss recent changes, archive quality varies by site.": "局限性：仅能找到先前存档的内容，可能错过近期变化，存档质量因网站而异。",
  "Limitations: Requires API key, limited to 10,000 queries/day on free tier, requires search engine configuration in Google Control Panel.": "局限性：需要API密钥，免费层每天限10,000次查询，需在Google控制面板中配置搜索引擎。",
  "Limitations: Requires paid API key with usage limits, newer service with evolving features.": "局限性：需要付费API密钥且有使用限制，较新的服务功能不断演进。",
  "Limitations: Requires paid API key with usage limits, newer service with less historical data coverage.": "局限性：需要付费API密钥且有使用限制，较新的服务历史数据覆盖较少。",
  "Limitations: Requires paid API key with usage limits, not specialized for academic or technical content.": "局限性：需要付费API密钥且有使用限制，不专门针对学术或技术内容。",
  "Limits the number of top search results included in the knowledge summary shown to the LLM during question generation. Set to 10 to show only the top 10 results, reducing token usage. Set to 0 for unlimited. Note: This only affects question generation prompts — final answer synthesis always uses all results.": "限制问题生成时包含在知识摘要中的顶部搜索结果数量，该摘要会展示给LLM。设置为10仅显示前10个结果，减少令牌使用。设置为0表示无限制。注意：这仅影响问题生成提示——最终答案综合始终使用所有结果。",
  "Limits which search engines this run may use.": "限定本次研究可使用的搜索引擎。",
