  "Notes": "研究笔记",
  "Notes - Deep Research System": "研究笔记 · Astro DRA",
  "Nothing is removed. Even predatory journals (score 1) pass because the filter keeps everything ≥ 1.": "不会删除任何内容。即使是掠夺性期刊（评分1）也会通过，因为过滤器保留所有≥1的内容。",
  "Nothing to preview": "没有可预览的内容",
  "Notification": "通知",
  "Notification service URL(s). Supports multiple comma-separated URLs to send notifications to multiple destinations (e.g., discord://YOUR_WEBHOOK_ID/YOUR_TOKEN, mailto://YOUR_USER:YOUR_PASS@smtp.example.com?to=recipient@example.com). See <a href=\"https://github.com/LearningCircuit/local-deep-research/blob/main/docs/NOTIFICATIONS.md\" target=\"_blank\">documentation</a> for supported services.": "通知服务URL。支持多个以逗号分隔的URL，用于向多个目的地发送通知（例如，discord://YOUR_WEBHOOK_ID/YOUR_TOKEN, mailto://YOUR_USER:YOUR_PASS@smtp.example.com?to=recipient@example.com）。有关支持的服务，请参阅<a href=\"https://github.com/LearningCircuit/local-deep-research/blob/main/docs/NOTIFICATIONS.md\" target=\"_blank\">文档</a>。",
  "Notifications": "通知",
  "Now": "现在",
  "Number of Examples": "示例数量",
  "Number of Links": "链接数量",
  "Number of Ratings": "评分数量",
  "Number of Requests": "请求数量",
  "Number of characters per chunk when splitting documents for embedding. Larger chunks (1000+) keep more context but search is less precise. Smaller chunks (<500) are more granular but may cut off important context. Affects new indexing only.": "分割文档进行嵌入时每个块包含的字符数。较大的块（1000以上）保留更多上下文，但搜索精度较低。较小的块（500以下）更细致，但可能截断重要上下文。仅影响新索引。",
  "Number of days a 'Remember Me' session remains valid before requiring re-login.": "“记住我”会话在需要重新登录前保持有效的天数。",
  "Number of due subscriptions to pick up and schedule in each check cycle. Larger batches are more efficient but use more memory. Range: 1-20.": "每个检查周期中要拾取并安排的到期订阅数量。较大的批次更高效，但会占用更多内存。范围：1-20。",
  "Number of independent searches per report section when generating structured reports. Increases coverage but also increases API usage.": "生成结构化报告时，每个报告部分进行的独立搜索次数。增加覆盖率，但也会增加API使用量。",
  "Number of previously generated report sections to include as context when writing new sections. Helps the LLM avoid repeating content. Higher values increase context size but may exceed smaller model limits. Default is 3.": "编写新部分时，作为上下文包含的先前生成的报告部分数量。帮助LLM避免重复内容。较高的值会增加上下文大小，但可能超出较小模型的限制。默认值为3。",
  "Number of recent requests to remember per search engine for calculating optimal wait times. At least 3 successful requests are needed before wait time estimates start updating.": "每个搜索引擎记住的近期请求数量，用于计算最佳等待时间。至少需要3次成功请求后，等待时间估算才会开始更新。",
  "Number of research cycles to perform": "要执行的研究循环次数",
  "Number of search queries to generate and execute per iteration. More questions increase coverage but also increase API calls and processing time.": "每次迭代生成并执行的搜索查询数量。更多问题增加覆盖率，但也增加API调用和处理时间。",
  "Number of search-and-refine cycles to run. Each iteration generates follow-up questions based on previous results to progressively deepen the research. More iterations yield better coverage but increase search and LLM API usage.": "要运行的搜索与细化循环次数。每次迭代基于先前结果生成后续问题，以逐步深化研究。更多迭代带来更好的覆盖率，但增加搜索和LLM API使用量。",
  "Number of web searches to perform per report section. Higher values increase research depth for each section but also increase search engine queries and processing time. Default is 2.": "每个报告部分执行的网络搜索次数。较高的值增加每个部分的研究深度，但也增加搜索引擎查询和处理时间。默认值为2。",
  "Numbered List": "编号列表",
  "Numbers with hyperlinks [1]": "带超链接的数字 [1]",
  "Numbers without hyperlinks [1]": "不带超链接的数字 [1]",
  "Numeric library ID. Optional for personal libraries — it is detected automatically from the API key (a pasted username is resolved too). Required for group libraries: the group's numeric ID (use the group picker, or the number in the group's URL).": "数字文献库ID。个人文献库可选——它会从API密钥自动检测（粘贴的用户名也会被解析）。群组文献库必填：群组的数字ID（使用群组选择器，或群组URL中的数字）。",
