  "Ollama service is not running.": "Ollama服务未运行。",
  "Ollama, LM Studio, LlamaCpp (all free)": "Ollama、LM Studio、LlamaCpp（均免费）",
  "Ollama, LM Studio, and self-hosted models are free ($0.00)": "Ollama、LM Studio和自托管模型免费（$0.00）",
  "On by default — untick to pause all Zotero syncing without removing your credentials.": "默认开启——取消勾选以暂停所有Zotero同步，而无需移除您的凭据。",
  "Once a collection is indexed, its embedding settings are locked. To change settings for an existing collection, you must re-index the entire collection, which will delete the current index.": "一旦资料合集被索引，其嵌入设置将被锁定。要更改现有资料合集的设置，您必须重新索引整个资料合集，这将删除当前索引。",
  "One or more notes were too long; only the first part was used in the synthesis.": "一条或多条笔记过长；合成时仅使用了第一部分。",
  "Only extracted text is stored. Smallest footprint, no PDF viewing.": "仅存储提取的文本。占用空间最小，不支持PDF查看。",
  "Only extracted text stored. Smallest database size.": "仅存储提取的文本。数据库大小最小。",
  "Only extracted text stored. Smallest footprint, re-download PDFs when needed.": "仅存储提取的文本。占用空间最小，需要时重新下载PDF。",
  "Only import items tagged (optional)": "仅导入带标签的项目（可选）",
  "Only import items tagged with ALL of these comma-separated Zotero tags (case-insensitive). Leave empty to import everything. This filters what is imported; changing it does not remove items already imported.": "仅导入带有所有这些逗号分隔的Zotero标签（不区分大小写）的条目。留空以导入所有内容。这过滤了导入的内容；更改它不会移除已导入的条目。",
  "Only needed for authenticated Ollama instances": "仅用于需要认证的Ollama实例",
  "Only needed if your LM Studio server requires an API key": "仅当您的LM Studio服务器需要API密钥时使用",
  "Only retrieve search snippets instead of full webpage content. Reduces API usage and processing time, but provides less context for analysis.": "仅检索搜索摘要而非完整网页内容。减少API使用和处理时间，但提供的分析上下文较少。",
  "Only return open access papers that are freely available": "仅返回可免费获取的开放获取论文",
  "Only return papers published after this date (YYYY-MM-DD format, leave empty for all dates)": "仅返回在此日期之后发表的论文（YYYY-MM-DD格式，留空表示所有日期）",
  "Only {{0}} results per query. Accuracy likely severely degraded.": "每个查询仅{{0}}条结果。准确性可能严重下降。",
