  "Optional - give your subscription a memorable name": "可选 - 为您的订阅起一个易记的名称",
  "Optional API key for LM Studio if you've enabled authentication. Leave empty for the default no-auth setup.": "用于LM Studio的可选API密钥，如果您已启用认证。对于默认的无认证设置，请留空。",
  "Optional API key for Ollama if you've put it behind a proxy that requires authentication. Leave empty for the default no-auth setup.": "用于Ollama的可选API密钥，如果您将其置于需要认证的代理之后。对于默认的无认证设置，请留空。",
  "Optional API key for `llama-server` if it's behind an auth proxy. Leave empty if your llama-server has no authentication.": "用于`llama-server`的可选API密钥，如果它位于认证代理之后。如果您的llama-server没有认证，请留空。",
  "Optional API key for your Anthropic-compatible endpoint. Leave blank for self-hosted servers that don't require authentication.": "用于您的兼容Anthropic端点的可选API密钥。对于不需要认证的自托管服务器，请留空。",
  "Optional list of SearXNG engines to restrict searches to (e.g. [\"kagi\", \"brave\", \"wikipedia\", \"arxiv\"] — this field is JSON, so the names must be double-quoted). When empty (default), SearXNG uses all of its own configured engines. Names must match the engines enabled on your SearXNG instance — see /engines on the instance for the full list.": "用于限制搜索范围的SearXNG引擎可选列表（例如，[\"kagi\", \"brave\", \"wikipedia\", \"arxiv\"] — 此字段为JSON，因此名称必须用双引号括起来）。当为空（默认）时，SearXNG使用其自身配置的所有引擎。名称必须与您的SearXNG实例上启用的引擎匹配 — 请参阅实例上的/engines获取完整列表。",
  "Optional output vector dimensionality. Only applies to OpenAI text-embedding-3 models (which support truncation); ignored for other models including most local servers. Leave blank to use the model's native dimensionality.": "可选的输出向量维度。仅适用于OpenAI text-embedding-3模型（支持截断）；其他模型（包括大多数本地服务器）忽略此设置。留空以使用模型的原生维度。",
  "Optional, for authenticated instances": "可选，用于需要认证的实例",
  "Optional, leave empty if not required": "可选，如不需要请留空",
