  "Per-query limit on results kept after LLM relevance filtering. Raw results (controlled by 'Max Results') are filtered for relevance, then this setting caps how many are kept. Only applies when relevance filtering is active for the search engine.": "LLM相关性过滤后保留结果的每次查询限制。原始结果（由“最大结果数”控制）经过相关性过滤，然后此设置限制保留的数量。仅当搜索引擎启用了相关性过滤时适用。",
  "Performance": "性能",
  "Performance Analysis": "性能分析",
  "Performance Variations:": "性能变化：",
  "Performing advanced news analysis...": "正在执行高级新闻分析...",
  "Performing research...": "正在执行研究...",
  "Periodically index ALL unindexed documents in the background — both library uploads that weren't indexed immediately (e.g. because the immediate auto-index queue was full) AND research downloads that haven't been ingested into your library yet. Idempotent and processed in small batches per run; already-indexed documents are skipped. Off by default. Requires \"Enable Document Scheduler\" above to be on — the background sweep only runs while the document scheduler is enabled.": "在后台定期索引所有未索引的文档——包括未立即索引的文献库上传（例如，因为即时自动索引队列已满）以及尚未纳入文献库的研究下载。幂等且每次运行以小批量处理；已索引的文档会被跳过。默认关闭。需要上面的“启用文档调度器”开启——后台扫描仅在文档调度器启用时运行。",
  "Periodically re-sync the configured collections in the background (downloads new items, updates changed ones, and removes items deleted in Zotero). Requires the Zotero integration to be enabled.": "在后台定期重新同步配置的资料合集（下载新条目，更新已更改的条目，并移除在Zotero中删除的条目）。需要启用Zotero集成。",
  "Periodically to ensure database integrity": "定期以确保数据库完整性",
  "Permanently delete all selected documents and their associated data.": "永久删除所有选中的文档及其关联数据。",
  "Permanently delete this document, including PDF and text content. This cannot be undone.": "永久删除此文档，包括PDF和文本内容。此操作无法撤销。",
  "Permanently delete this document? This cannot be undone.": "永久删除此文档？此操作无法撤销。",
  "Permanently hide the 'Elasticsearch points at a non-private host' banner that appears when the Elasticsearch engine is active but its hosts (or cloud_id) do not look like private/local addresses (document queries would leave the machine; a private-only egress scope excludes the engine). Dismiss when a hosted endpoint such as Elastic Cloud is intentional.": "永久隐藏当Elasticsearch引擎激活但其主机（或cloud_id）看起来不是私有/本地地址时出现的“Elasticsearch指向非私有主机”横幅（文档查询将离开机器；仅私有外部访问范围排除该引擎）。当托管端点如Elastic Cloud是有意使用时，请关闭。",
  "Permanently hide the 'LLM provider is cloud-hosted' banner. Separate from the public-egress dismiss flag so acknowledging fresh-install noise never suppresses this critical warning.": "永久隐藏“LLM提供方为云托管”横幅。与公共外部访问关闭标志分开，以便确认全新安装的噪音永远不会抑制此关键警告。",
  "Permanently hide the 'Paperless-ngx points at a non-private host' banner that appears when the Paperless engine is active but its API URL does not look like a private/local address (document queries would leave the machine; a private-only egress scope excludes the engine).": "永久隐藏当Paperless引擎激活但其API URL看起来不是私有/本地地址时出现的“Paperless-ngx指向非私有主机”横幅（文档查询将离开机器；仅私有外部访问范围排除该引擎）。",
  "Permanently hide the 'SearXNG is disabled: private URL not approved' banner that appears when SearXNG is active (selected as the search engine, or enabled for auto/agent search) but its private/localhost instance URL has no operator approval (allowlist, blanket opt-in, or env-lock) in the server environment.": "永久隐藏当SearXNG激活（被选为搜索引擎，或启用自动/代理搜索）但其私有/本地主机实例URL在服务器环境中没有操作员批准（允许列表、全面选择或环境锁定）时出现的“SearXNG已禁用：私有URL未批准”横幅。",
  "Permanently hide the 'document chunks will be sent to OpenAI' (cloud embeddings) banner. Separate from the public-egress dismiss flag so acknowledging fresh-install noise never suppresses this critical warning.": "永久隐藏“文档块将发送到OpenAI”（云嵌入）横幅。与公共外部访问关闭标志分开，以便确认全新安装的噪音永远不会抑制此关键警告。",
  "Permanently hide the 'public search egress enabled' banner (the fresh-install informational one). The critical cloud-LLM and cloud-embeddings banners have their OWN dismiss flags so this can't silently hide them.": "永久隐藏“公共搜索外部访问已启用”横幅（全新安装信息性横幅）。关键的云LLM和云嵌入横幅有自己的关闭标志，因此这不能静默隐藏它们。",
  "Permanently hide the informational banner that states what the Adaptive egress scope resolves to (public / private / both) for the current primary engine.": "永久隐藏说明当前主引擎的自适应外部访问范围解析为（公共/私有/两者）的信息横幅。",
  "Permanently hide the warning shown when using a large model (70B+ parameters) with a local provider and high context window, which may exceed available GPU memory.": "永久隐藏使用大型模型（70B+参数）与本地提供方和高上下文窗口时可能超出可用GPU内存的警告。",
  "Permanently hide the warning shown when your local LLM context window is set above 8,192 tokens, which may cause memory issues on some hardware.": "永久隐藏当本地LLM上下文窗口设置为超过8,192个令牌时显示的警告，这可能会在某些硬件上导致内存问题。",
  "Personal libraries are detected from the API key. For a group library, use “List groups” below to find its ID.": "个人文献库通过API密钥检测。对于群组文献库，请使用下方的“列出群组”查找其ID。",
