  "Research methodology. 'source-based': Finds and extracts from sources (good for comprehensive research). 'focused-iteration': Uses entity-based progressive exploration (optimized for factual Q&A, ~95% SimpleQA accuracy, requires larger context windows). 'focused-iteration-standard': Comprehensive variant of focused-iteration with broader exploration. 'topic-organization': Organizes research around discovered topic clusters. 'langgraph-agent': Autonomous agentic research where the LLM decides what to search and when to synthesize.": "研究方法论。'基于来源'：从来源中查找并提取（适用于全面研究）。'聚焦迭代'：使用基于实体的渐进式探索（针对事实问答优化，约95%的SimpleQA准确率，需要更大的上下文窗口）。'聚焦迭代-标准'：聚焦迭代的全面变体，探索范围更广。'主题组织'：围绕发现的主题集群组织研究。'langgraph代理'：自主代理式研究，由LLM决定搜索什么以及何时综合。",
