  "Send notification when a research task completes successfully. This is the primary completion alert for tracking long-running research.": "当研究任务成功完成时发送通知。这是跟踪长时间运行研究的主要完成提醒。",
  "Send notification when a research task fails or encounters an error. Enables rapid problem detection without monitoring the web interface.": "当研究任务失败或遇到错误时发送通知。无需监控网页界面即可快速发现问题。",
  "Send notification when a subscription refresh fails or encounters errors. Helps identify broken subscriptions that need attention.": "当订阅刷新失败或遇到错误时发送通知。有助于识别需要关注的失效订阅。",
  "Send notification when authentication fails for external API services (e.g., invalid or expired API keys). Alerts you to broken integrations that need attention.": "当外部API服务的身份验证失败时（例如，无效或过期的API密钥）发送通知。提醒您注意需要修复的集成问题。",
  "Send notification when news subscriptions detect new content matching your configured topics.": "当新闻订阅检测到与您配置的主题匹配的新内容时发送通知。",
  "Send notification when research is added to the processing queue. Useful in queue mode to confirm your request was accepted and is waiting to be processed.": "当研究被添加到处理队列时发送通知。在队列模式下，有助于确认您的请求已被接受并正在等待处理。",
