  "Sync finished.": "同步完成。",
  "Sync from the Zotero desktop app running on this machine (local API at localhost:23119) instead of the cloud Web API. No API key needed, and it can read locally-stored / linked-file attachments the cloud API can't. Requires Zotero 7+ with the local API enabled in its preferences, and Zotero running during sync. Caution on shared/multi-user hosts: the desktop app's local API is unauthenticated, so any user or process on the server able to reach localhost:23119 can read that Zotero library.": "从本机运行的 Zotero 桌面应用（本地 API 位于 localhost:23119）同步，而非云端 Web API。无需 API 密钥，且可读取云端 API 无法访问的本地存储/链接文件附件。需要 Zotero 7+ 并在其偏好设置中启用本地 API，且同步期间 Zotero 需保持运行。注意：在共享/多用户主机上，桌面应用的本地 API 未经过身份验证，因此服务器上任何能访问 localhost:23119 的用户或进程都可读取该 Zotero 文献库。",
  "Sync now": "立即同步",
  "Sync started in the background. Status updates below.": "同步已在后台启动。状态更新如下。",
