  "Test the currently selected embedding model to ensure it's working correctly.": "测试当前选定的嵌入模型，确保其正常工作。",
  "Test your current settings against standard datasets": "针对标准数据集测试您当前的设置",
  "Testing embedding model... For local providers this may take a moment while the model is loaded into memory.": "正在测试嵌入模型...对于本地提供方，模型加载到内存中可能需要一点时间。",
