  "Time range filter for Brave results (e.g., 'd' for day, 'w' for week, 'm' for month, 'y' for year).": "Brave结果的时间范围过滤器（例如，'d'表示天，'w'表示周，'m'表示月，'y'表示年）。",
  "Time range filter for SerpAPI results: 'd' (day), 'w' (week), 'm' (month), 'y' (year), or 'all' (no filter). Overridden by the global Search → Time Period setting whenever that is set (the normal case); applies only to programmatic snapshots without it.": "SerpAPI结果的时间范围过滤器：'d'（天）、'w'（周）、'm'（月）、'y'（年）或'all'（不过滤）。当全局“搜索→时间段”设置被设置时（通常情况），该设置会被覆盖；仅适用于未设置该设置的程序化快照。",
  "Time range filter for Tavily results: 'd' (day), 'w' (week), 'm' (month), 'y' (year), or 'all' (no filter). Overridden by the global Search → Time Period setting whenever that is set (the normal case); applies only to programmatic snapshots without it.": "Tavily结果的时间范围过滤器：'d'（天）、'w'（周）、'm'（月）、'y'（年）或'all'（无过滤）。当全局搜索→时间周期设置被设置时（通常情况），此设置会被覆盖；仅适用于没有该设置的编程快照。",
  "Time range filter for search results. Limits results to content published within the specified period (day, week, month, year, or all time).": "搜索结果的时间范围过滤器。将结果限制为在指定时间段（天、周、月、年或全部时间）内发布的内容。",
