  "Timezone for date calculations (e.g., news subscription YYYY-MM-DD placeholder). Use 'UTC' for server time or specify your local timezone.": "日期计算的时区（例如，新闻订阅的YYYY-MM-DD占位符）。使用'UTC'表示服务器时间，或指定您的本地时区。",
