  "Token Usage:": "Token使用量：",
  "Token budget passed to Ollama for each embedding call. If your chunks tokenize to more than this, Ollama returns HTTP 500 and indexing fails. Increase if you see 'input length exceeds the context length'. Default 8192 is safe for chunk sizes up to ~5000 characters.": "传递给Ollama的每个嵌入调用的Token预算。如果您的块分词后超过此值，Ollama将返回HTTP 500且索引失败。如果看到'input length exceeds the context length'，请增加此值。默认8192对于约5000字符的块大小是安全的。",
  "Token usage directly impacts API costs. Input tokens are typically cheaper than output tokens. Quick research mode uses fewer tokens but detailed mode provides more comprehensive results.": "Token使用直接影响API成本。输入Token通常比输出Token便宜。快速研究模式使用较少的Token，但详细模式提供更全面的结果。",
