  "Tokens are pieces of text (roughly 4 characters or 3/4 of a word). Higher token counts = longer research but more thorough results.": "Token是文本片段（大约4个字符或3/4个单词）。较高的Token计数=更长的研究但更彻底的结果。",
  "Tokens per Call": "每次调用的Token数",
  "Tokens. Must exceed the largest chunk after tokenization. Increase if Ollama returns \"input length exceeds the context length\".": "Token数。必须超过分词后的最大块。如果Ollama返回\"input length exceeds the context length\"，请增加此值。",
