  "Upload multiple files at once using drag & drop": "使用拖放一次上传多个文件",
  "Upload your documents, index them, then select a collection as 'search engine' when researching. AI will search YOUR files instead of the web.": "上传您的文档，索引它们，然后在研究时选择一个资料合集作为'搜索引擎'。AI将搜索您的文件，而不是网络。",
