  "Usage distribution across different providers": "不同提供方的使用分布",
  "Use 'Get All Research PDFs' to download PDFs from tracked sources. Use 'Text Only' for just searchable text.": "使用'获取所有研究PDF'从跟踪来源下载PDF。使用'仅文本'仅获取可搜索文本。",
  "Use 'Sync Library' after moving or deleting files manually to update the database.": "手动移动或删除文件后，使用'同步文献库'更新数据库。",
  "Use 'Text Only' for initial exploration, then download PDFs for papers you want to keep permanently.": "使用'仅文本'进行初步探索，然后为要永久保留的论文下载PDF。",
  "Use HTTPS": "使用HTTPS",
  "Use In Auto Search": "在自动搜索中使用",
  "Use LLM to generate descriptive chat session titles instead of simple query truncation. When disabled, titles are the first 100 characters of the query.": "使用LLM生成描述性聊天会话标题，而不是简单的查询截断。禁用时，标题为查询的前100个字符。",
  "Use LLM to optimize natural language queries for better search results": "使用LLM优化自然语言查询以获得更好的搜索结果",
  "Use Local Zotero (desktop app)": "使用本地Zotero（桌面应用）",
  "Use Template": "使用模板",
  "Use Unrestricted Cloud Context Window": "使用不受限制的云上下文窗口",
  "Use descriptive names like \"AI Research 2024\" instead of generic names": "使用描述性名称，如“AI研究2024”，而不是通用名称",
  "Use in Research": "在研究中使用",
  "Use insights to adjust settings - switch to models or engines that consistently rate higher.": "利用洞察调整设置——切换到持续评分更高的模型或引擎。",
  "Use larger-context models, reduce query size, or be more specific in your research questions.": "使用更大上下文的模型，减少查询规模，或在研究问题中更具体。",
  "Use local models for exploratory research, and cloud models for final reports needing maximum quality.": "探索性研究使用本地模型，最终报告需要最高质量时使用云模型。",
  "Use markdown tables for structured output": "使用Markdown表格进行结构化输出",
  "Use reasonable example counts to avoid overwhelming search engines. Default of 75 examples is good for testing.": "使用合理的示例数量，避免压倒搜索引擎。默认的75个示例适合测试。",
  "Use smaller models for simple tasks": "简单任务使用较小模型",
  "Use sources from previous research": "使用先前研究的来源",
  "Use the": "使用",
  "Use the local desktop app API (localhost:23119)": "使用本地桌面应用API（localhost:23119）",
  "Use these estimates as a general guide only. The true value of local models includes privacy, control, and independence benefits beyond just cost savings.": "这些估算仅作为一般指南。本地模型的真正价值包括隐私、控制和独立性，而不仅仅是成本节省。",
  "Use this editor to directly modify configuration values. You can add new parameters not shown in the UI, and they will be preserved across saves. Changes here override the UI settings.": "使用此编辑器直接修改配置值。您可以添加界面中未显示的新参数，它们将在保存时保留。此处的更改会覆盖界面设置。",
  "Use this group": "使用此组",
  "Use your personal rating history to optimize your research workflow. Instead of relying on intuition alone, leverage actual performance statistics to identify which LLM models, search engines, and research approaches deliver the best results for your specific needs.": "利用您的个人评分历史优化研究工作流。不要仅依赖直觉，利用实际性能统计来识别哪些LLM模型、搜索引擎和研究方法能为您的特定需求提供最佳结果。",
  "User": "用户",
