  "Warnings": "警告",
  "Wayback Machine is free and does not require an API key.": "Wayback Machine是免费的，不需要API密钥。",
  "We currently achieve close to 0% accuracy on BrowseComp.": "我们目前在BrowseComp上的准确率接近0%。",
  "We're always looking for new ideas and recommendations! If you have suggestions for features, improvements, or if you encounter bugs or things that don't work optimally, please share them on": "我们一直在寻找新的想法和建议！如果您有功能、改进的建议，或者遇到错误或运行不佳的情况，请分享到",
  "Weaknesses": "弱点",
