  "collections: they stay off the public internet under Public-only / Adaptive egress scope and force local LLM/embeddings inference when used, so their contents never reach a cloud model. Marking a collection public never uploads or exposes its documents — they always stay local; it only permits cloud inference over them. Check this only for non-sensitive content you're happy to process with cloud inference.": "资料合集：在仅公开/自适应外部访问范围下，它们不会出现在公共互联网上，并且在使用时会强制本地LLM/嵌入推理，因此其内容永远不会到达云模型。将资料合集标记为公开绝不会上传或暴露其文档——它们始终保留在本地；它仅允许对其执行云推理。仅当您愿意使用云推理处理非敏感内容时才勾选此项。",
