  "~280K journals + conferences with h-index, 2-yr mean citedness, citation count, publisher, ISSN. Quality is derived from h-index thresholds (≥150 → 10, ≥75 → 8, ≥40 → 7, ≥20 → 6, ≥10 → 5, else → 4) and a Q1–Q4 quartile is computed from cited_by_count percentiles per source type.": "约280K个期刊和会议，包含h指数、2年平均被引量、被引次数、出版商、ISSN。质量由h指数阈值决定（≥150 → 10，≥75 → 8，≥40 → 7，≥20 → 6，≥10 → 5，否则 → 4），并根据每种来源类型的被引次数百分位数计算Q1–Q4四分位数。",
  "~{{0}} tokens lost.": "约{{0}}个令牌丢失。",
  "±{{0}}% (95% CI, n={{1}})": "±{{0}}%（95%置信区间，n={{1}}）",
  "— Also drop default/unknown venues (score 4). Repository aggregators, garbled refs, brand-new or niche venues with no h-index data.": "— 同时删除默认/未知场所（得分4）。仓库聚合器、混乱的参考文献、全新或小众且无h指数数据的场所。",
  "— Also drop moderate journals (score 5). Conferences and DOAJ-only OA journals start to disappear.": "— 同时删除中等期刊（得分5）。会议和仅DOAJ的开放获取期刊开始消失。",
  "— Drop only predatory (score 1). Keep everything else, including default/unknown venues.": "— 仅删除掠夺性期刊（得分1）。保留其他所有内容，包括默认/未知场所。",
  "— Drops only confirmed predatory journals from the Stop Predatory Journals list — minus any rescued by the whitelist (DOAJ-listed or h-index above PREDATORY_WHITELIST_HINDEX). Default/unknown and low-h-index journals are kept.": "— 仅从Stop Predatory Journals列表中删除已确认的掠夺性期刊 — 减去白名单中拯救的期刊（DOAJ收录或h指数高于PREDATORY_WHITELIST_HINDEX）。默认/未知和低h指数期刊保留。",
  "— Elite only. Nature, Science, NEJM tier (h-index ≥ 75 / ≥ 150). Aggressive — most search results will be filtered out.": "— 仅精英。Nature、Science、NEJM级别（h指数 ≥ 75 / ≥ 150）。激进 — 大多数搜索结果将被过滤掉。",
  "— Filter is effectively off. Nothing is removed (predatory journals score 1, but threshold 1 means \"≥ 1\" so they pass).": "— 过滤器实际关闭。不删除任何内容（掠夺性期刊得分为1，但阈值1表示“≥ 1”，因此它们通过）。",
  "— Keep only good journals (h-index ≥ 20).": "— 仅保留优质期刊（h指数 ≥ 20）。",
  "— Keep only strong Q1 journals (h-index ≥ 40).": "— 仅保留强Q1期刊（h指数 ≥ 40）。",
  "— Same as 2 (no scores fall in this gap — values 2, 3, 9 are never emitted).": "— 与2相同（此区间无得分 — 值2、3、9从不发出）。",
  "— Same as 2 (no scores fall in this gap).": "— 与2相同（此区间无得分）。",
