  "— other strategies (source-based, focused-iteration, topic-organization) ignore this flag, so leaving it unchecked only hides the collection from the agent's specialised tool list. The match-in dropdown on the New Research form greys the collection out when LangGraph is the selected strategy, and the run is refused at submit time if you try to use it anyway. This is a usability switch only — it does not change privacy or egress.": "— 其他策略（基于来源、聚焦迭代、主题组织）忽略此标志，因此取消选中仅将资料合集从代理的专用工具列表中隐藏。当选择LangGraph作为策略时，新研究表单中的匹配下拉框会将资料合集置灰，如果仍尝试使用，提交时会拒绝运行。这仅是一个可用性开关 — 不改变隐私或外部访问。",
  "— other strategies (source-based, focused-iteration, topic-organization) ignore this flag, so leaving it unchecked only hides the collection from the agent's specialised tool list. The match-in dropdown on the New Research form greys the collection out when LangGraph is the selected strategy, and the run is refused at submit time if you try to use it anyway. Usability switch only — it does not change privacy or egress.": "— 其他策略（基于来源、聚焦迭代、主题组织）忽略此标志，因此取消选中仅将资料合集从代理的专用工具列表中隐藏。当选择LangGraph作为策略时，新研究表单中的匹配下拉框会将资料合集置灰，如果仍尝试使用，提交时会拒绝运行。仅可用性开关 — 不改变隐私或外部访问。",
